				if (sanctuaryIn > -1)
				{
					MapMgr.sanctuaryMgr.sanctuaries[sanctuaryIn].RefreshChar(p);
					if (MapMgr.sanctuaryMgr.sanctuaries[sanctuaryIn].shrine)
					{
						menuMgr.active = false;
